42	// https://github.com/gopro/gpr/blob/a513701afce7b03173213a2f67dfd9dd28fa1868/source/lib/vc5_decoder/vlc.h
43	struct RLV {
44	  const uint_fast8_t size; //!< Size of code word in bits
45	  const uint32_t bits;     //!< Code word bits right justified
46	  const uint16_t count;    //!< Run length
47	  const uint8_t value;     //!< Run value (unsigned)
48	};
49	#define RLVTABLE(n)                                                            \
50	  struct {                                                                     \
51	    const uint32_t length;                                                     \
52	    const RLV entries[n];                                                      \
53	  } constexpr
