541	void VC5Decompressor::parseLargeCodeblock(const ByteStream& bs) {
542	  static const auto subband_wavelet_index = []() {
543	    std::array<int, numSubbands> wavelets;
544	    int wavelet = 0;
545	    for (auto i = wavelets.size() - 1; i > 0;) {
546	      for (auto t = 0; t < numWaveletLevels; t++) {
547	        wavelets[i] = wavelet;
548	        i--;
549	      }
550	      if (i > 0)
551	        wavelet++;
552	    }
553	    wavelets.front() = wavelet;
554	    return wavelets;
555	  }();
556	  static const auto subband_band_index = []() {
557	    std::array<int, numSubbands> bands;
558	    bands.front() = 0;
559	    for (auto i = 1U; i < bands.size();) {
560	      for (int t = 1; t <= numWaveletLevels;) {
561	        bands[i] = t;
562	        t++;
563	        i++;
564	      }
565	    }
566	    return bands;
567	  }();
568	
569	  const int idx = subband_wavelet_index[mVC5.iSubband];
570	  const int band = subband_band_index[mVC5.iSubband];
571	
572	  auto& wavelets = channels[mVC5.iChannel].wavelets;
573	
574	  Wavelet& wavelet = wavelets[idx];
575	  if (wavelet.isBandValid(band)) {
576	    ThrowRDE("Band %u for wavelet %u on channel %u was already seen", band, idx,
577	             mVC5.iChannel);
578	  }
579	
580	  std::unique_ptr<Wavelet::AbstractBand>& dstBand = wavelet.bands[band];
581	  if (mVC5.iSubband == 0) {
582	    assert(band == 0);
583	    // low-pass band, only one, for the smallest wavelet, per channel per image
584	    dstBand = std::make_unique<Wavelet::LowPassBand>(bs, mVC5.lowpassPrecision);
585	  } else {
586	    dstBand = std::make_unique<Wavelet::HighPassBand>(bs, mVC5.quantization);
587	  }
588	  wavelet.setBandValid(band);
589	
590	  // If this wavelet is fully specified, mark the low-pass band of the
591	  // next lower wavelet as specified.
592	  if (idx > 0 && wavelet.allBandsValid()) {
593	    Wavelet& nextWavelet = wavelets[idx - 1];
594	    assert(!nextWavelet.isBandValid(0));
595	    nextWavelet.bands[0] = std::make_unique<Wavelet::ReconstructableBand>();
596	    nextWavelet.setBandValid(0);
597	  }
598	}
599	
600	void VC5Decompressor::decode(unsigned int offsetX, unsigned int offsetY,
601	                             unsigned int width, unsigned int height) {
602	  if (offsetX || offsetY || mRaw->dim != iPoint2D(width, height))
603	    ThrowRDE("VC5Decompressor expects to fill the whole image, not some tile.");
604	
605	  initVC5LogTable();
606	
607	  const std::vector<DecodeableBand> allDecodeableBands = [&]() {
608	    std::vector<DecodeableBand> bands;
609	    bands.reserve(numSubbandsTotal);
610	    // All the high-pass bands for all wavelets,
611	    // in this specific order of decreasing worksize.
612	    for (int waveletLevel = 0; waveletLevel < numWaveletLevels;
613	         waveletLevel++) {
614	      for (auto channelId = 0; channelId < numChannels; channelId++) {
615	        for (int bandId = 1; bandId <= numHighPassBands; bandId++) {
616	          auto& channel = channels[channelId];
617	          auto& wavelet = channel.wavelets[waveletLevel];
618	          auto* band = wavelet.bands[bandId].get();
619	          auto* decodeableHighPassBand =
620	              dynamic_cast<Wavelet::HighPassBand*>(band);
621	          bands.emplace_back(decodeableHighPassBand, wavelet);
622	        }
623	      }
624	    }
625	    // The low-pass bands at the end. I'm guessing they should be fast to
626	    // decode.
627	    for (Channel& channel : channels) {
628	      // Low-pass band of the smallest wavelet.
629	      Wavelet& smallestWavelet = channel.wavelets.back();
630	      auto* decodeableLowPassBand =
631	          dynamic_cast<Wavelet::LowPassBand*>(smallestWavelet.bands[0].get());
632	      bands.emplace_back(decodeableLowPassBand, smallestWavelet);
633	    }
634	    assert(allDecodeableBands.size() == numSubbandsTotal);
635	    return bands;
636	  }();
637	
638	#ifdef HAVE_OPENMP
639	  bool exceptionThrown = false;
640	#pragma omp parallel default(none) shared(exceptionThrown)                     \
641	    num_threads(rawspeed_get_number_of_processor_cores())
642	  {
643	#endif
644	#ifdef HAVE_OPENMP
645	#pragma omp for schedule(guided)
646	#endif
647	    for (auto decodeableBand = allDecodeableBands.begin();
648	         decodeableBand < allDecodeableBands.end(); ++decodeableBand) {
649	      try {
650	        decodeableBand->band->decode(decodeableBand->wavelet);
651	      } catch (RawspeedException& err) {
652	        // Propagate the exception out of OpenMP magic.
653	        mRaw->setError(err.what());
654	#ifdef HAVE_OPENMP
655	#pragma omp atomic write
656	        exceptionThrown = true;
657	#pragma omp cancel for
658	#else
659	        throw;
660	#endif
661	      }
662	    }
663	
664	#ifdef HAVE_OPENMP
665	#pragma omp cancel parallel if (exceptionThrown)
666	#endif
667	
668	    // And now, for every channel, recursively reconstruct the low-pass bands.
669	    for (int waveletLevel = numWaveletLevels - 1; waveletLevel > 0;
670	         waveletLevel--) {
671	#ifdef HAVE_OPENMP
672	#pragma omp for schedule(static)
673	#endif
674	      for (auto channel = channels.begin(); channel < channels.end();
675	           ++channel) {
676	        Wavelet& wavelet = channel->wavelets[waveletLevel];
677	        Wavelet& nextWavelet = channel->wavelets[waveletLevel - 1];
678	
679	        auto& reconstructableBand = nextWavelet.bands[0];
680	        reconstructableBand->decode(wavelet);
681	
682	        wavelet.clear(); // we no longer need it.
683	      }
684	    }
685	
686	    // Finally, for each channel, reconstruct the final lowpass band.
687	#ifdef HAVE_OPENMP
688	#pragma omp for schedule(static)
689	#endif
690	    for (auto channel = channels.begin(); channel < channels.end(); ++channel) {
691	      Wavelet& wavelet = channel->wavelets.front();
692	      channel->band.decode(wavelet);
693	    }
694	
695	    // And finally!
696	    combineFinalLowpassBands();
697	
698	#ifdef HAVE_OPENMP
699	  }
700	
701	  std::string firstErr;
702	  if (mRaw->isTooManyErrors(1, &firstErr)) {
703	    assert(exceptionThrown);
704	    ThrowRDE("Too many errors encountered. Giving up. First Error:\n%s",
705	             firstErr.c_str());
706	  } else {
707	    assert(!exceptionThrown);
708	  }
709	#endif
710	}
711	
712	void VC5Decompressor::combineFinalLowpassBands() const noexcept {
713	  const Array2DRef<uint16_t> out(reinterpret_cast<uint16_t*>(mRaw->getData()),
714	                                 static_cast<unsigned int>(mRaw->dim.x),
715	                                 static_cast<unsigned int>(mRaw->dim.y),
716	                                 mRaw->pitch / sizeof(uint16_t));
717	
718	  const unsigned int width = out.width / 2;
719	  const unsigned int height = out.height / 2;
720	
721	  const Array2DRef<const int16_t> lowbands0 = Array2DRef<const int16_t>(
722	      channels[0].band.data.data(), channels[0].width, channels[0].height);
723	  const Array2DRef<const int16_t> lowbands1 = Array2DRef<const int16_t>(
724	      channels[1].band.data.data(), channels[1].width, channels[1].height);
725	  const Array2DRef<const int16_t> lowbands2 = Array2DRef<const int16_t>(
726	      channels[2].band.data.data(), channels[2].width, channels[2].height);
727	  const Array2DRef<const int16_t> lowbands3 = Array2DRef<const int16_t>(
728	      channels[3].band.data.data(), channels[3].width, channels[3].height);
729	
730	  // Convert to RGGB output
731	#ifdef HAVE_OPENMP
732	#pragma omp for schedule(static) collapse(2)
733	#endif
734	  for (unsigned int row = 0; row < height; ++row) {
735	    for (unsigned int col = 0; col < width; ++col) {
736	      const int mid = 2048;
737	
738	      int gs = lowbands0(col, row);
739	      int rg = lowbands1(col, row) - mid;
740	      int bg = lowbands2(col, row) - mid;
741	      int gd = lowbands3(col, row) - mid;
742	
743	      int r = gs + 2 * rg;
744	      int b = gs + 2 * bg;
745	      int g1 = gs + gd;
746	      int g2 = gs - gd;
747	
748	      out(2 * col + 0, 2 * row + 0) = static_cast<uint16_t>(mVC5LogTable[r]);
749	      out(2 * col + 1, 2 * row + 0) = static_cast<uint16_t>(mVC5LogTable[g1]);
750	      out(2 * col + 0, 2 * row + 1) = static_cast<uint16_t>(mVC5LogTable[g2]);
751	      out(2 * col + 1, 2 * row + 1) = static_cast<uint16_t>(mVC5LogTable[b]);
752	    }
753	  }
754	}
755	
756	// static
757	void VC5Decompressor::getRLV(BitPumpMSB* bits, int* value,
758	                             unsigned int* count) {
759	  unsigned int iTab;
760	
761	  static constexpr auto maxBits = 1 + table17.entries[table17.length - 1].size;
762	
763	  // Ensure the maximum number of bits are cached to make peekBits() as fast as
764	  // possible.
765	  bits->fill(maxBits);
766	  for (iTab = 0; iTab < table17.length; ++iTab) {
767	    if (table17.entries[iTab].bits ==
768	        bits->peekBitsNoFill(table17.entries[iTab].size))
769	      break;
770	  }
771	  if (iTab >= table17.length)
772	    ThrowRDE("Code not found in codebook");
773	
774	  bits->skipBitsNoFill(table17.entries[iTab].size);
775	  *value = table17.entries[iTab].value;
776	  *count = table17.entries[iTab].count;
777	  if (*value != 0) {
778	    if (bits->getBitsNoFill(1))
779	      *value = -(*value);
780	  }
781	}
782	
783	} // namespace rawspeed
